// SidebarOrder names every row of the sidebar in the order drawn, the
// settled ones after a bar. While it stays the same a changed thread can
// be patched as one row (SidebarRow) instead of redrawing the list.
func SidebarOrder(d SidebarData) string {
	var b strings.Builder
	b.WriteString(d.Mode)
	if d.Mode == "project" {
		for _, p := range d.Projects {
			b.WriteString("/" + p.ID)
			for _, t := range inboxOrder(d.Threads) {
				if t.ProjectID == p.ID && listed(t) {
					b.WriteString("," + t.ID)
				}
			}
		}
	} else {
		for _, t := range inboxOrder(d.Threads) {
			if listed(t) {
				b.WriteString("," + t.ID)
			}
		}
	}
	b.WriteString("|")
	for _, t := range snoozedThreads(d.Threads) {
		b.WriteString("," + t.ID)
	}
	b.WriteString("|")
	for _, t := range settledThreads(d.Threads) {
		b.WriteString("," + t.ID)
	}
	return b.String()
}

// SidebarRow is thread id's row as Sidebar draws it, for a patch of that
// row alone; nil when the thread has no row.
func SidebarRow(d SidebarData, id string) templ.Component {
	byID := map[string]store.Project{}
	for _, p := range d.Projects {
		byID[p.ID] = p
	}
	for i, t := range settledThreads(d.Threads) {
		if t.ID == id {
			return SettledRow(t, byID[t.ProjectID], t.ID == d.Current, prOf(t, d.PRs), i >= settledShown)
		}
	}
	for _, t := range snoozedThreads(d.Threads) {
		if t.ID == id {
			return SnoozedRow(t, byID[t.ProjectID], t.ID == d.Current)
		}
	}
	for _, t := range d.Threads {
		if t.ID == id && listed(t) {
			return ThreadRow(t, byID[t.ProjectID], t.ID == d.Current, d.Mode != "project", d.Looks[t.Agent], unread(t, d.Current, d.Seen), prOf(t, d.PRs))
		}
	}
	return nil
}

// settledShown is how many settled rows show before "Show more".
const settledShown = 10

// newThreadProject is the project the search row's new-thread button
// uses: the current thread's, else the first.
func newThreadProject(d SidebarData) string {
	for _, t := range d.Threads {
		if t.ID == d.Current {
			return t.ProjectID
		}
	}
	if len(d.Projects) > 0 {
		return d.Projects[0].ID
	}
	return ""
}

// inboxOrder puts what needs a look first: threads waiting for an
// approval, then running ones, then pinned; the rest keep the store's
// order (last activity first).
func inboxOrder(ts []store.Thread) []store.Thread {
	rank := func(t store.Thread) int {
		switch {
		case t.Status == domain.StatusAwaitingApproval:
			return 0
		case t.Status == domain.StatusRunning:
			return 1
		case t.Pinned:
			return 2
		}
		return 3
	}
	out := append([]store.Thread(nil), ts...)
	sort.SliceStable(out, func(i, j int) bool { return rank(out[i]) < rank(out[j]) })
	return out
}

// settledThreads are the archived threads whose turn is over, the last
// one settled first.
func settledThreads(ts []store.Thread) []store.Thread {
	var out []store.Thread
	for _, t := range ts {
		if t.Archived && !active(t) {
			out = append(out, t)
		}
	}
	at := func(t store.Thread) time.Time {
		if t.SettledAt.IsZero() {
			return t.UpdatedAt
		}
		return t.SettledAt
	}
	sort.SliceStable(out, func(i, j int) bool { return at(out[i]).After(at(out[j])) })
	return out
}

// initials is the project's two-letter mark; initialsStyle its colour,
// a hue from the name so a project keeps its colour everywhere.
func initials(name string) string {
	r := []rune(strings.ToUpper(name))
	var out []rune
	for _, c := range r {
		if unicode.IsLetter(c) || unicode.IsDigit(c) {
			out = append(out, c)
		}
		if len(out) == 2 {
			break
		}
	}
	if len(out) == 0 {
		return "?"
	}
	return string(out)
}

func initialsStyle(name string) string {
	h := 0
	for _, c := range name {
		h = (h*31 + int(c)) % 360
	}
	return fmt.Sprintf("--proj-hue: %d", h)
}

